articles:
.parent {
  display: grid;
  place-items: center;   /* centred both ways */
  min-height: 100vh;
}

p {
  color: #1a9fff;
  font-size: 1.25rem;
  font-weight: 600;
}

body {
  background: #111113;                                  /* a colour */
  background: linear-gradient(135deg, #1a9fff, #8e4ec6);   /* or a gradient */
}

.row {
  display: flex;
  gap: 16px;
  align-items: center;
}
.row .wide { flex: 1; }

.cards {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 16px;
}

.card {
  border-radius: 16px;
  box-shadow: 0 10px 30px rgba(0, 0, 0, .15);
}
.avatar { border-radius: 50%; }   /* a circle */

button {
  padding: 10px 18px;
  border: 0;
  border-radius: 10px;
  background: #1a9fff;
  color: #fff;
  font: inherit;
  cursor: pointer;
  transition: filter .15s, transform .1s;
}
button:hover  { filter: brightness(1.1); }
button:active { transform: scale(.96); }

/* in the <head>:  <meta name="viewport" content="width=device-width, initial-scale=1"> */

.box { width: min(100%, 600px); }

@media (max-width: 600px) {
  .row { flex-direction: column; }
}

.box { transition: transform .3s ease; }
.box:hover { transform: translateY(-6px); }

@keyframes spin { to { transform: rotate(360deg); } }
.loader { animation: spin 1s linear infinite; }

:root { --bg: #ffffff; --text: #1b1b1f; }

@media (prefers-color-scheme: dark) {
  :root { --bg: #111113; --text: #f2f2f3; }
}

body { background: var(--bg); color: var(--text); }

body {
  font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
  line-height: 1.5;
}
